import json
import subprocess
from pathlib import Path

from matrisk import run_pipeline


def _fake_project(tmp_path):
    (tmp_path / "ML/notebooks").mkdir(parents=True)
    (tmp_path / "Data/raw").mkdir(parents=True)
    (tmp_path / "Data/raw/source.csv").write_text("value\n1\n", encoding="utf-8")
    (tmp_path / "ML/outputs/notebook_01").mkdir(parents=True)
    # This stale artifact must not be counted as generated by the current run.
    (tmp_path / "ML/outputs/notebook_01/run_summary.json").write_text("{}", encoding="utf-8")
    return tmp_path


def _records(root):
    ledger = root / "ML/outputs/execution_ledger.jsonl"
    return [json.loads(line) for line in ledger.read_text(encoding="utf-8").splitlines()]


def test_runner_records_success_failure_interrupt_and_stale_outputs(tmp_path, monkeypatch):
    root = _fake_project(tmp_path)
    calls = iter([
        subprocess.CompletedProcess([], 0, "", ""),
        subprocess.CompletedProcess([], 0, "", ""),
        subprocess.CompletedProcess([], 7, "", "notebook exploded"),
        subprocess.TimeoutExpired("nbconvert", 1, stderr="cell hung"),
    ])

    def fake_run(command, **kwargs):
        if command[0] == "git":
            raise subprocess.CalledProcessError(1, command)
        outcome = next(calls)
        if isinstance(outcome, subprocess.TimeoutExpired):
            raise outcome
        return outcome

    monkeypatch.setattr(run_pipeline.subprocess, "run", fake_run)
    notebook = run_pipeline.NOTEBOOKS[1]
    assert run_pipeline.run([notebook], root) == 0
    first = _records(root)[-1]
    assert first["status"] == "success"
    assert first["return_code"] == 0
    assert first["input_sha256"]["Data/raw/source.csv"]
    assert first["started_at_utc"] and first["completed_at_utc"]
    assert first["expected_outputs_present"] == ["ML/outputs/notebook_01/run_summary.json"]
    assert first["outputs_changed_during_run"] == []
    assert first["output_status"] == "expected_present_but_not_generated"

    (root / "Data/raw/source.csv").write_text("value\n2\n", encoding="utf-8")
    assert run_pipeline.run([notebook], root) == 0
    changed = _records(root)[-1]
    assert changed["input_changes_since_previous_run"]["changed"] == ["Data/raw/source.csv"]
    assert changed["outputs_changed_during_run"] == []

    assert run_pipeline.run([notebook], root) == 1
    failed = _records(root)[-1]
    assert failed["status"] == "failure" and failed["return_code"] == 7
    assert failed["failure_type"] == "NonZeroExit" and "notebook exploded" in failed["error"]

    assert run_pipeline.run([notebook], root) == 1
    interrupted = _records(root)[-1]
    assert interrupted["status"] == "interrupted"
    assert interrupted["failure_type"] == "TimeoutExpired" and "cell hung" in interrupted["error"]


def test_runner_reports_missing_expected_output_even_on_process_success(tmp_path, monkeypatch):
    root = _fake_project(tmp_path)
    (root / "ML/outputs/notebook_01/run_summary.json").unlink()

    def fake_run(command, **kwargs):
        if command[0] == "git":
            raise subprocess.CalledProcessError(1, command)
        return subprocess.CompletedProcess(command, 0, "", "")

    monkeypatch.setattr(run_pipeline.subprocess, "run", fake_run)
    assert run_pipeline.run([run_pipeline.NOTEBOOKS[1]], root) == 0
    record = _records(root)[-1]
    assert record["status"] == "success"  # Process result, not artifact inference.
    assert record["missing_expected_outputs"] == ["ML/outputs/notebook_01/run_summary.json"]
    assert record["output_status"] == "missing_expected_outputs"
